#pragma once
#include "core/scene_control_entries.hpp"
#include "core/text_strip_publication.hpp"
#include "core/text_tile_publication.hpp"
#include "core/actor_phase_ending.hpp"
namespace rolo {
struct EndingSceneState{SceneControlState scene;TextStripState strip;TextTileState tiles;std::uint32_t controlled{},base{},entrance_actor{},target{};std::uint16_t camera_x{},camera_y{};};
struct EndingSpawn{std::uint32_t head{},tail{};};
struct EndingSceneServices:SceneControlServices,EndingCompletionServices{virtual void palette_job(std::uint32_t,std::uint32_t,std::uint32_t)=0;virtual EndingSpawn spawn(std::uint32_t,std::uint32_t,std::uint32_t,std::uint8_t)=0;virtual ActorState& actor(std::uint32_t)=0;};
inline void initialize_complete_ending(EndingSceneState&s,EndingSceneServices&v){s.scene.text.frame_hook=0x9a88;for(auto op:{SceneStep::ResetForegroundRows,SceneStep::ResetBackgroundRows,SceneStep::PreparePaletteRotation})v.step(op);v.step(SceneStep::LoadTitle,0x46d4c);v.step(SceneStep::ClearRegion,0x6484);s.strip.source=0x13a10;s.strip.cursor&=0xffff0000u;s.tiles.row=28;s.tiles.attributes=0x2000;s.tiles.base=0xc000;s.tiles.row_mask=31;s.tiles.erase_row=20;s.scene.selector=65531;v.step(SceneStep::FadeIn);v.step(SceneStep::Music,3,65535);}
inline void initialize_partial_ending(EndingSceneState&s,EndingSceneServices&v){s.scene.text.frame_hook=0x9b34;v.step(SceneStep::ResetForegroundRows);v.step(SceneStep::ResetBackgroundRows);v.step(SceneStep::LoadTitle,0x46d4c);v.palette_job(0xffffc740,0xffffc60c,0x4b5aa);s.strip.source=0x13ae6;s.strip.cursor&=0xffff0000u;s.tiles.row=28;s.tiles.attributes=0xa000;s.tiles.base=0xc000;s.tiles.row_mask=31;s.tiles.erase_row=0;}
inline void step_complete_ending(EndingSceneState&s,EndingSceneServices&v){if(s.scene.text.frame_hook!=0x9a88)initialize_complete_ending(s,v);v.step(SceneStep::ParseText,0x5e82);if(!(s.strip.source&0x80000000u)||!s.scene.busy)return;wait_scene_busy(s.scene,v);v.step(SceneStep::FadeBlack);s.scene.main_state=0x15aa;}
inline void step_partial_ending(EndingSceneState&s,EndingSceneServices&v){if(s.scene.text.frame_hook!=0x9b34)initialize_partial_ending(s,v);for(auto op:{SceneStep::Replay,SceneStep::DrainTransfers,SceneStep::BuildActive,SceneStep::PlayerPresentation,SceneStep::Animate,SceneStep::Render})v.step(op);v.step(SceneStep::ParseText,0x5e82);if(!s.strip.source){v.step(SceneStep::FadeBlack);s.scene.main_state=0x15aa;}}
inline void spawn_ending_actors(EndingSceneState&s,EndingSceneServices&v){s.camera_x=s.camera_y=100;auto first=v.spawn(0x1575e,0xfa0000,0xf10000,0);s.target=first.tail;auto second=v.spawn(0x13ecc,0x1de0000,0xf10000,255);s.controlled=s.base=s.entrance_actor=second.head;auto&a=v.actor(second.head);a.byte(126,a.byte(126)|2);}
inline void initialize_ending_entrance(EndingSceneState&s,EndingSceneServices&v){s.scene.text.frame_hook=0x9be2;for(auto op:{SceneStep::FadeBlack,SceneStep::ResetForegroundRows,SceneStep::ResetBackgroundRows,SceneStep::ResetTextSprites,SceneStep::ResetWordQueue,SceneStep::ResetByteQueue,SceneStep::ClearPlane})v.step(op);reset_scene_planes(s.scene,v);for(auto op:{SceneStep::ClearRegion,SceneStep::LoadTitle,SceneStep::ResetActors,SceneStep::ResetGraphics})v.step(op);spawn_ending_actors(s,v);s.scene.timer=500;s.scene.selector=65535;v.step(SceneStep::FadeIn);v.step(SceneStep::Music,16,65535);}
inline void walk_ending_actor(EndingSceneState&s,EndingSceneServices&v){auto&a=v.actor(s.controlled);auto x=std::uint16_t(a.word(12)-1);std::uint16_t selector=4;if(signed_word(x)<=322){x=322;selector=92;v.actor(s.target).byte(46,255);}a.word(12,x);a.word(70,selector);}
inline void initialize_ending_palette_stage(EndingSceneState&s,EndingSceneServices&v){v.palette_job(0xffffc66c,0xffffc5ec,0x4b7ca);v.palette_job(0xffffc740,0xffffc60c,0x4b7ca);v.palette_job(0xffffc814,0xffffc62c,0x32360);v.palette_job(0xffffc8e8,0xffffc64c,0x4b7ca);s.scene.timer=std::uint16_t(s.scene.timer-1);}
inline void step_ending_stage(EndingSceneState&s,EndingSceneServices&v){if(signed_word(s.scene.timer)>0){--s.scene.timer;return;}switch(s.scene.timer){case 0:initialize_ending_palette_stage(s,v);return;case 65535:ending_wait_actor(v.actor(s.target).byte(6),s.scene.timer);return;case 65534:ending_completion_state(s.scene.main_state,v);return;default:throw std::out_of_range("Ending stage selector admission");}}
inline void step_ending_entrance(EndingSceneState&s,EndingSceneServices&v){if(s.scene.text.frame_hook!=0x9be2)initialize_ending_entrance(s,v);for(auto op:{SceneStep::Replay,SceneStep::DrainTransfers,SceneStep::BuildActive})v.step(op);walk_ending_actor(s,v);for(auto op:{SceneStep::PlayerPresentation,SceneStep::Animate,SceneStep::Render})v.step(op);step_ending_stage(s,v);}
}
